package com.chondrimaishrat.elearning.assignment;
import com.chondrimaishrat.elearning.course.*; import com.chondrimaishrat.elearning.enrollment.EnrollmentRepository; import com.chondrimaishrat.elearning.user.UserAccount; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class AssignmentService {private final AssignmentRepository assignments;private final AssignmentSubmissionRepository submissions;private final CourseRepository courses;private final EnrollmentRepository enrollments;public AssignmentService(AssignmentRepository a,AssignmentSubmissionRepository s,CourseRepository c,EnrollmentRepository e){assignments=a;submissions=s;courses=c;enrollments=e;} public List<Assignment> list(Long c){return assignments.findByCourseIdOrderByIdDesc(c);}@Transactional public void create(UserAccount i,Long c,String t,String ins,LocalDateTime due){Course course=courses.findById(c).orElseThrow();if(!course.getInstructor().getId().equals(i.getId()))throw new IllegalArgumentException("You can only create assignments for your own course.");assignments.save(new Assignment(course,t,ins,due));}@Transactional public void submit(UserAccount s,Long a,String link){Assignment x=assignments.findById(a).orElseThrow();if(!enrollments.existsByStudentIdAndCourseId(s.getId(),x.getCourse().getId()))throw new IllegalArgumentException("Enroll before submitting.");if(submissions.existsByAssignmentIdAndStudentId(a,s.getId()))throw new IllegalArgumentException("You already submitted this assignment.");submissions.save(new AssignmentSubmission(x,s,link));}@Transactional public void grade(UserAccount i,Long id,int grade,String feedback){AssignmentSubmission sub=submissions.findById(id).orElseThrow();if(!sub.getAssignment().getCourse().getInstructor().getId().equals(i.getId()))throw new IllegalArgumentException("Not your assignment.");if(grade<0||grade>100)throw new IllegalArgumentException("Grade must be 0-100.");sub.grade(grade,feedback);}}
